@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + assignedCustomer : Customer
}

class Contract {
  + contractNumber : int
  + signingDate : date
  + insuredAmount : double
  + policyType : string
}

abstract class Policy {
  + policyText : string
}

class LifePolicy {}

class CarLiabilityPolicy {}

class TheftPolicy {}

class Claim {
  + claimId : int
  + claimDate : date
  + description : string
}

class ClaimCase {
  + caseId : int
  + claimDate : date
  + status : string
}

abstract class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class MaterialDamageEstimator {}

class PhysicalDamageEstimator {}

Customer "1" -- "0..*" Broker
Broker "1" -- "1" Customer
Customer "1" -- "0..*" Contract
Contract "1" -- "1" Policy
Policy "0..1" -- "1" LifePolicy
Policy "0..1" -- "1" CarLiabilityPolicy
Policy "0..1" -- "1" TheftPolicy
Customer "1" -- "0..*" Claim
Claim "1" -- "*" ClaimCase
Estimator "0..*" -- "1..*" ClaimCase

@enduml

